+  - key: my-flag
+    name: My Flag
+    variants:
+      - key: known
+        name: Known
+    rules:
+      - segment: missing-segment
+        distributions:
+          - variant: missing-variant
+            rollout: 100
+      - segment:
+          keys: [known, another-missing-segment]
+        distributions:
+          - variant: known
+            rollout: 100
+  - key: bool-flag
+    name: Boolean Flag
+    type: BOOLEAN_FLAG_TYPE
+    rules:
+      - segment: missing-for-boolean
+        distributions: []
+`
